propuesta.texto_viejo:
"chat.message": async (input, output) => {
  sessionID = input && input.sessionID ? input.sessionID : sessionID;
  lastActivity = Date.now();
  const ctx = leerCanal();
  if (!ctx) return;
  output.parts.push({
    id: "canal-" + Date.now(),
    sessionID,
    messageID: input && input.messageID ? input.messageID : "user",
    type: "text",
    text: ctx,
    synthetic: true,
  });
},

propuesta.texto_nuevo:
"chat.message": async (input, output) => {
  sessionID = input && input.sessionID ? input.sessionID : sessionID;
  lastActivity = Date.now();
  const r = leerCanal();
  if (!r) return;
  output.parts.push({
    id: "prt_" + Date.now() + "_" + Math.random().toString(36).slice(2, 8),
    sessionID,
    messageID: input && input.messageID ? input.messageID : "user",
    type: "text",
    text: r.ctx,
    synthetic: true,
  });
  marcarCanal(r.rutas);
},

